// Actual NSTask and private pipes, synthetic Node controller. Not a payload
// installation, production NSBundle admission, physical input or AppKit UI test.
#import "InstallerPipeTransport.h"
#import <CommonCrypto/CommonDigest.h>

static NSString *NodePath;
static NSString *FixtureSource;
static NSString *FixtureRoot;
static NSMutableArray *ActiveFixtures;
static NSMutableArray *Cleanup;
static void Require(BOOL condition,NSString *code){if(!condition)@throw [NSException exceptionWithName:@"TestAssertion" reason:code userInfo:nil];}
static void Pump(double seconds){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:seconds];do{[[NSRunLoop mainRunLoop]runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:0.002]];}while([end timeIntervalSinceNow]>0);}
static BOOL Until(BOOL(^predicate)(void),double seconds){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:seconds];while(!predicate()&&[end timeIntervalSinceNow]>0)Pump(0.002);return predicate();}
static NSString *Hash(NSString *path){NSFileHandle *file=[NSFileHandle fileHandleForReadingAtPath:path];Require(file!=nil,@"test file missing");CC_SHA256_CTX ctx;CC_SHA256_Init(&ctx);while(YES){NSData *b=[file readDataOfLength:1024*1024];if(!b.length)break;CC_SHA256_Update(&ctx,b.bytes,(CC_LONG)b.length);}[file closeFile];unsigned char bytes[CC_SHA256_DIGEST_LENGTH];CC_SHA256_Final(bytes,&ctx);NSMutableString *hex=[NSMutableString new];for(int i=0;i<CC_SHA256_DIGEST_LENGTH;i++)[hex appendFormat:@"%02x",bytes[i]];return hex;}
static NSDictionary *Configuration(NSString *mode){NSString *path=[FixtureRoot stringByAppendingPathComponent:[mode stringByAppendingString:@".mjs"]];if(![[NSFileManager defaultManager]fileExistsAtPath:path])Require([[NSFileManager defaultManager]copyItemAtPath:FixtureSource toPath:path error:nil],@"fixture copy failed");return @{@"contents":FixtureRoot,@"node":@{@"path":NodePath,@"sha256":Hash(NodePath)},@"controller":@{@"path":path,@"sha256":Hash(path)}};}
static SEPInstallerPipeTransport *Make(NSString *mode){SEPInstallerPipeTransport *t=[[SEPInstallerPipeTransport alloc]initWithVerifiedConfiguration:Configuration(mode) manifestSHA:[@"a" stringByPaddingToLength:64 withString:@"a" startingAtIndex:0]];[ActiveFixtures addObject:t];Require([t.snapshot[@"started"]boolValue],@"actual Node child not started");return t;}
static NSDictionary *Request(SEPInstallerPipeTransport *t,NSString *op,NSDictionary *input){__block NSDictionary *reply=nil;__block NSUInteger completions=0;[t requestOperation:op input:input completion:^(NSDictionary *v){completions++;reply=v;}];Require(Until(^BOOL{return reply!=nil;},2),@"response deadline");Require(completions==1,@"duplicate completion");return reply;}
static void Close(SEPInstallerPipeTransport *t){__block BOOL terminated=NO;__block NSInteger exit=-1;__block BOOL signal=YES;[t observeTermination:^(NSInteger code,BOOL signalled){terminated=YES;exit=code;signal=signalled;}];NSDictionary *v=Request(t,@"close",@{});Require([v[@"status"]isEqual:@"pass"]&&[v[@"phase"]isEqual:@"closed"]&&[v[@"resourcesReleased"]isEqual:@YES],@"closed receipt missing");Require(Until(^BOOL{return terminated;},2),@"actual child termination/EOF missing");Require(exit==0&&!signal,@"abnormal fixture exit");Require([t.snapshot[@"stdoutEOF"]boolValue]&&[t.snapshot[@"processExited"]boolValue],@"termination not backed by EOF plus actual exit");}
static void RejectMode(NSString *mode){SEPInstallerPipeTransport *t=Make(mode);NSDictionary *v=Request(t,@"preview",@{});Require(![v[@"status"]isEqual:@"pass"],@"malformed response accepted");Require([t.snapshot[@"phase"]isEqual:@"blocked"],@"protocol failure did not lock admission");NSUInteger n=[t.snapshot[@"requestsDispatched"]unsignedIntegerValue];v=Request(t,@"preview",@{});Require(![v[@"status"]isEqual:@"pass"]&&[t.snapshot[@"requestsDispatched"]unsignedIntegerValue]==n,@"poisoned transport dispatched again");}
static void Run(NSString *name,void(^body)(void),NSMutableArray *results){ActiveFixtures=[NSMutableArray new];@try{body();[results addObject:@{@"name":name,@"status":@"pass"}];}@catch(NSException *e){[results addObject:@{@"name":name,@"status":@"fail",@"code":e.reason?:@"ASSERTION"}];}@finally{for(SEPInstallerPipeTransport *t in ActiveFixtures){BOOL started=[t.snapshot[@"started"]boolValue];BOOL ended=!started||Until(^BOOL{return [t.snapshot[@"processExited"]boolValue]&&[t.snapshot[@"stdoutEOF"]boolValue];},4.5);[Cleanup addObject:@{@"test":name,@"started":@(started),@"fixtureTerminatedAndDrained":@(ended),@"forcedTermination":@NO,@"path":started?@"fixture normal completion or its own fixed four-second deadline":@"no child started"}];if(!ended)[results addObject:@{@"name":[name stringByAppendingString:@" cleanup"],@"status":@"fail",@"code":@"FIXTURE_CLEANUP_UNCONFIRMED"}];}ActiveFixtures=nil;}}

int main(int argc,const char **argv){@autoreleasepool{
 if(argc!=4)return 64;NodePath=[NSString stringWithUTF8String:argv[1]];FixtureSource=[NSString stringWithUTF8String:argv[2]];FixtureRoot=[NSString stringWithUTF8String:argv[3]];Require([[NSFileManager defaultManager]createDirectoryAtPath:FixtureRoot withIntermediateDirectories:NO attributes:nil error:nil],@"fixture directory must be fresh");setenv("NODE_OPTIONS","--trace-warnings",1);setenv("SEP_TRANSPORT_SECRET","synthetic-private-value",1);[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];Cleanup=[NSMutableArray new];NSMutableArray *results=[NSMutableArray new];
 Run(@"real child receives private binding and bounded preview then closes normally",^{SEPInstallerPipeTransport *t=Make(@"normal");NSDictionary *v=Request(t,@"preview",@{});Require([v[@"phase"]isEqual:@"preview"]&&[v[@"preview"][@"entries"]isEqual:@2],@"preview missing");Require([v[@"sequence"]isEqual:@1]&&[v[@"protocol"]isEqual:@1],@"binding envelope missing");Require([v[@"preview"][@"target"]containsString:@"安装"],@"Unicode summary changed");Close(t);},results);
 Run(@"UTF-8 split inside a multibyte character is reconstructed",^{SEPInstallerPipeTransport *t=Make(@"split");NSDictionary *v=Request(t,@"preview",@{});Require([v[@"status"]isEqual:@"pass"]&&[v[@"preview"][@"target"]containsString:@"安装"],@"split UTF-8 rejected/corrupted");Close(t);},results);
 Run(@"second operation while busy is refused locally without duplicate dispatch",^{SEPInstallerPipeTransport *t=Make(@"slow");__block NSDictionary *first=nil;[t requestOperation:@"preview" input:@{} completion:^(NSDictionary *v){first=v;}];NSDictionary *second=Request(t,@"confirm",@{@"planHash":[@"b" stringByPaddingToLength:64 withString:@"b" startingAtIndex:0]});Require([second[@"code"]isEqual:@"SEP_INSTALLER_UI_BUSY"],@"parallel request not refused");Require([t.snapshot[@"requestsDispatched"]unsignedIntegerValue]==1,@"second request dispatched");Require(Until(^BOOL{return first!=nil;},2)&&[first[@"status"]isEqual:@"pass"],@"accepted operation lost");Close(t);},results);
 Run(@"unknown operation and extra request path never reach child",^{SEPInstallerPipeTransport *t=Make(@"normal");NSDictionary *a=Request(t,@"write",@{@"path":@"/outside"});NSDictionary *b=Request(t,@"preview",@{@"path":@"/outside"});Require(![a[@"status"]isEqual:@"pass"]&&![b[@"status"]isEqual:@"pass"],@"unknown request accepted");Require([t.snapshot[@"requestsDispatched"]unsignedIntegerValue]==0,@"invalid request sent to child");Close(t);},results);
 Run(@"wrong nonce and out-of-order sequence lock the private channel",^{RejectMode(@"wrong-nonce");RejectMode(@"wrong-sequence");},results);
 Run(@"response with extra field is refused",^{RejectMode(@"extra-field");},results);
 Run(@"duplicate response frames cannot complete an operation twice",^{SEPInstallerPipeTransport *t=Make(@"duplicate");__block NSUInteger completions=0;[t requestOperation:@"preview" input:@{} completion:^(NSDictionary *v){(void)v;completions++;}];Require(Until(^BOOL{return [t.snapshot[@"processExited"]boolValue]&&[t.snapshot[@"stdoutEOF"]boolValue];},2),@"duplicate fixture not drained");Require(completions==1&&[t.snapshot[@"phase"]isEqual:@"blocked"],@"duplicate completion or unlocked channel");NSUInteger n=[t.snapshot[@"requestsDispatched"]unsignedIntegerValue];NSDictionary *v=Request(t,@"preview",@{});Require(![v[@"status"]isEqual:@"pass"]&&[t.snapshot[@"requestsDispatched"]unsignedIntegerValue]==n,@"duplicate allowed later dispatch");},results);
 Run(@"response exceeding sixteen KiB is rejected before JSON parsing",^{RejectMode(@"oversize");},results);
 Run(@"invalid UTF-8 cannot be replaced or silently accepted",^{RejectMode(@"invalid-utf8");},results);
 Run(@"EOF with a partial frame reports incomplete response",^{RejectMode(@"truncated");},results);
 Run(@"large stderr is continuously drained and never exposed",^{SEPInstallerPipeTransport *t=Make(@"stderr");NSDictionary *v=Request(t,@"preview",@{});Require([v[@"status"]isEqual:@"pass"],@"stderr backpressure blocked response");Require([t.snapshot[@"stderrBytesBounded"]unsignedIntegerValue]>0&&[t.snapshot[@"stderrBytesBounded"]unsignedIntegerValue]<=65536,@"stderr diagnostic not bounded");NSData *snapshot=[NSJSONSerialization dataWithJSONObject:t.snapshot options:0 error:nil];NSString *text=[[NSString alloc]initWithData:snapshot encoding:NSUTF8StringEncoding];Require(![text containsString:@"PRIVATE-STDERR"]&&![text containsString:FixtureRoot],@"sensitive diagnostic leaked");Close(t);},results);
 Run(@"termination observer waits for stdout EOF after actual parent exit",^{SEPInstallerPipeTransport *t=Make(@"exit-eof");__block BOOL notified=NO;__block BOOL normal=NO;[t observeTermination:^(NSInteger code,BOOL signal){normal=(code==0&&!signal);notified=YES;}];NSDictionary *v=Request(t,@"close",@{});Require([v[@"phase"]isEqual:@"closed"],@"last frame lost");Require(Until(^BOOL{return [t.snapshot[@"processExited"]boolValue];},1),@"parent did not exit");Require(!notified&&![t.snapshot[@"stdoutEOF"]boolValue],@"exit alone notified before inherited stdout EOF");Require(Until(^BOOL{return notified;},2)&&normal,@"EOF did not release normal observer");},results);
 Run(@"twenty immediate result-and-exit children preserve final receipt ordering",^{for(NSUInteger n=0;n<20;n++){SEPInstallerPipeTransport *t=Make(@"race");__block BOOL gotReply=NO;__block BOOL terminated=NO;__block BOOL replyBeforeExit=NO;[t observeTermination:^(NSInteger code,BOOL signal){replyBeforeExit=gotReply;terminated=(code==0&&!signal);}];[t requestOperation:@"close" input:@{} completion:^(NSDictionary *v){gotReply=[v[@"phase"]isEqual:@"closed"]&&[v[@"resourcesReleased"]isEqual:@YES];}];Require(Until(^BOOL{return terminated;},2)&&gotReply&&replyBeforeExit,@"final frame/exit race dropped or reordered receipt");}},results);
 Run(@"blocked close is delivered without killing or claiming released resources",^{SEPInstallerPipeTransport *t=Make(@"blocked");__block BOOL terminated=NO;__block BOOL expected=NO;[t observeTermination:^(NSInteger code,BOOL signal){expected=(code==9&&!signal);terminated=YES;}];NSDictionary *v=Request(t,@"close",@{});Require([v[@"status"]isEqual:@"blocked"]&&v[@"resourcesReleased"]==nil,@"blocked close promoted");Require(!terminated&&![t.snapshot[@"processExited"]boolValue],@"blocked close killed child");Require(Until(^BOOL{return terminated;},2)&&expected,@"fixture-owned shutdown not observed");},results);
 Run(@"changed admitted controller hash is refused before process launch",^{NSMutableDictionary *config=[Configuration(@"normal")mutableCopy];config[@"controller"]=@{@"path":config[@"controller"][@"path"],@"sha256":[@"0" stringByPaddingToLength:64 withString:@"0" startingAtIndex:0]};SEPInstallerPipeTransport *t=[[SEPInstallerPipeTransport alloc]initWithVerifiedConfiguration:config manifestSHA:[@"a" stringByPaddingToLength:64 withString:@"a" startingAtIndex:0]];[ActiveFixtures addObject:t];Require(![t.snapshot[@"started"]boolValue]&&[t.snapshot[@"code"]isEqual:@"SEP_INSTALLER_UI_ROLE_CHANGED"],@"changed role hash allowed");},results);
 NSUInteger passed=0;for(NSDictionary *r in results)if([r[@"status"]isEqual:@"pass"])passed++;NSDictionary *receipt=@{@"schema":@1,@"status":passed==results.count?@"pass":@"fail",@"scope":@"actual NSTask/private pipes with synthetic Node controller; no production admission, real installation or physical input",@"definitions":@15,@"results":results,@"passed":@(passed),@"failed":@(results.count-passed),@"cleanup":Cleanup,@"productInstalled":@NO};NSData *json=[NSJSONSerialization dataWithJSONObject:receipt options:NSJSONWritingPrettyPrinted error:nil];fwrite(json.bytes,1,json.length,stdout);fputc('\n',stdout);return passed==results.count?0:1;
}}
